// -------------------------------------------------------------------------------------------
// the declaration

/// [definition] **A refinement as declared** (module header): the receiving ring `R`, the words
/// `K`, each word's full ticks `w`, the stations `m` and the termination class, with the receiver's
/// grain `L_R` read from the ring's declared receiver.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Refinement {
    ring: usize,
    words: usize,
    span: usize,
    stations: usize,
    termination: usize,
    grain: u64,
}

impl Refinement {
    /// **Declare a refinement** on a field: refused unless the ring has a declared receiver (its
    /// receiving map `R` and grain), `K, w, m ≥ 1`, the stations lie within one turn of the
    /// receiving ring (`m ≤ d_R`) and the termination class is a class of the exterior chart.
    pub fn declare(
        field: &Field,
        ring: usize,
        words: usize,
        span: usize,
        stations: usize,
        termination: usize,
    ) -> Result<Self, HnnError> {
        let receiver = field
            .receivers()
            .iter()
            .find(|receiver| receiver.ring == ring)
            .ok_or(HnnError::MissingReceivingMap { ring })?;
        if words == 0 || span == 0 || stations == 0 {
            return Err(HnnError::NonpositiveDeclaration);
        }
        let period = field.ring(ring).period();
        if stations as u64 > period {
            return Err(HnnError::Shape {
                what: "the section's stations within one turn of the receiving ring",
                expected: period as usize,
                found: stations,
            });
        }
        if termination >= field.alphabet() {
            return Err(HnnError::CellOutside {
                code: termination,
                alphabet: field.alphabet(),
            });
        }
        if !receiver.tolerance.is_positive() {
            return Err(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            });
        }
        let grain = receiver
            .tolerance
            .recip()
            .ceil()
            .to_integer()
            .to_u64()
            .ok_or(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            })?;
        Ok(Self {
            ring,
            words,
            span,
            stations,
            termination,
            grain,
        })
    }

    /// `R`.
    pub fn ring(&self) -> usize {
        self.ring
    }

    /// `K`.
    pub fn words(&self) -> usize {
        self.words
    }

    /// `w`.
    pub fn span(&self) -> usize {
        self.span
    }

    /// `m`.
    pub fn stations(&self) -> usize {
        self.stations
    }

    /// The termination class.
    pub fn termination(&self) -> usize {
        self.termination
    }

    /// `L_R`.
    pub fn grain(&self) -> u64 {
        self.grain
    }
}

// -------------------------------------------------------------------------------------------
// the release

/// [definition] **A section's release** (`section_release`): the decision, the width over the
/// section's fibre, each station's top class, the plural stations, the emitted classes (the
/// released section up to its first termination; empty unless released) and the first station at
/// the termination class.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionRelease {
    pub decision: ReleaseReturn,
    pub width: Rat,
    pub classes: Vec<usize>,
    pub plural: Vec<usize>,
    pub emitted: Vec<usize>,
    pub terminated: Option<usize>,
}

impl SectionRelease {
    /// Whether the section was released at width zero.
    pub fn released(&self) -> bool {
        matches!(self.decision, ReleaseReturn::Released { .. })
    }
}

/// **A section's release from its stations' classes and its plural stations** ([`bank_release`]):
/// width zero exactly when no station is plural, the discrete metric's one otherwise,
/// attained at the first plural station, decided at tolerance zero by the holding rule through
/// `receiver::release`; the released classes read up to the first termination.
fn section_release(
    declared: &Refinement,
    classes: Vec<usize>,
    plural: Vec<usize>,
) -> Result<SectionRelease, HnnError> {
    let (diameter, attaining) = match plural.first() {
        Some(&station) => (
            Rat::one(),
            WidthWitness::Coordinate {
                coordinate: station,
            },
        ),
        None => (Rat::zero(), WidthWitness::Point),
    };
    let width = ReceiverWidth::declared(
        format!("the section on receiving ring {}", declared.ring),
        "every station's top class at the grain, over the grain fibre of its logits",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        classes.len().max(1),
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, false)?;
    let rule = DecisionRule::new(
        "the section's joint commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let decision = release(&rule, &options)?;
    let terminated = classes
        .iter()
        .position(|&class| class == declared.termination);
    let emitted = match &decision {
        ReleaseReturn::Released { .. } => classes[..terminated.unwrap_or(classes.len())].to_vec(),
        _ => Vec::new(),
    };
    Ok(SectionRelease {
        decision,
        width: width.diameter().clone(),
        classes,
        plural,
        emitted,
        terminated,
    })
}

/// [definition; agent-inferred, U6's order repair] **The partition a training refinement compares**
/// (module header): the corruption chart of absorbing (masked) diffusion read on the stations. The
/// number `v` of locked stations is drawn uniformly from `0 … m − 1`, then `v` stations uniformly
/// (a partial Fisher–Yates draw); the rest are compared. Every partition a generation passes through
/// (nothing locked, then more) is one this law draws with positive mass, and at least one station is
/// always compared. `true` marks a locked (placed, uncompared) station.
pub fn mask(draw: &mut Draw, stations: usize) -> Vec<bool> {
    let mut order: Vec<usize> = (0..stations).collect();
    let locked = draw.below(stations.max(1));
    for i in 0..locked {
        let j = i + draw.below(stations - i);
        order.swap(i, j);
    }
    let mut visible = vec![false; stations];
    for &station in &order[..locked] {
        visible[station] = true;
    }
    visible
}

// -------------------------------------------------------------------------------------------
// generation by the receiving bank

/// [definition; agent-inferred, September 29] **A section generated by the receiving bank**
/// ([`generate_by_bank`]): its release, the refinements it took, the stations each locked, the turn
/// readings made, and at every lock the bank's certificate (the members certified at the locked
/// reading's growth, and the executed turn's ticks whose balance closed, of those run), with each
/// lock's station, class, growth and runner-up growth; and the lock whose Floquet certificate was
/// refused, if one was, where the release stopped and held (September 30: a refused certificate
/// refuses the lock, never a tally). Where the material holds pair contacts closed (their distances
/// in `contacts`; [`BankPlacement::contacts`]), each decision's enclosures are the candidates' gains
/// over their own columns read alone ([`gain`], [`BankPlacement::pair_storage`]), not their growths.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BankGeneration {
    pub release: SectionRelease,
    pub refinements: usize,
    pub locks: Vec<Vec<usize>>,
    pub readings: usize,
    pub certified: usize,
    pub members: usize,
    pub ticks_closed: usize,
    pub ticks: usize,
    pub decisions: Vec<(usize, usize, Growth, Growth)>,
    pub uncertified: Option<(usize, usize)>,
    pub contacts: Vec<usize>,
}

/// [definition; agent-inferred, October 5; the
/// [joint gain's record](../../../../research/records/2026-10-05_THE_PAIR_GAIN_IS_THE_JOINED_BANKS_LOG_DETERMINANT.md)
/// §3, revising lane C's least member] **A candidate's gain on equal material, read by the joined
/// bank**: the bank's relative transport from the candidate's column alone to its pair storage
/// ([`BankPlacement::pair_storage`]), read by its members together, its determinant on their lines,
///
/// ```text
/// Γ(j, x) = ∏_m g_m(z_pair) / g_m(z_alone),   log Γ = Σ_m (λ_m(z_pair) − λ_m(z_alone)),   λ_m = log g_m
/// enclosed exactly: [∏_m L_pair,m / U_alone,m,  ∏_m U_pair,m / L_alone,m]
/// ```
///
/// with `g_m` member `m`'s growth over the turn (its Floquet multiplier's modulus, enclosed by
/// [`ReceivingBank::read_turn`]). Why the determinant ([proved-derived], the record §3): the bank's
/// joint monodromy is its members' block sum ([`ReceivingBank::read_turn`]), so the full work form
/// over the joint state, `TᵀG₁T − rG₀`, is the direct sum of the members' and no cross term is
/// dropped by reading them one by one; each member is recharted on its own (its metric is attained,
/// any positive multiple certifying alike), so a ratio of joint quadratic forms reads a weight
/// between members that no owner supplies, and its weight-free limit, the joint growth, is the
/// largest member's alone; the ratio's additive chart (`ℓ = log R`, the loss law) on the direct sum
/// `R = ⊕_m R_m` is `log det R = Σ_m log det R_m`, the one joint reading in which a member whose two
/// storages turn alike (neutral, `g_m(z_pair) = g_m(z_alone)`) does not move the comparison. The
/// least member is not that reading: it is one member's, and a neutral member caps it at one. On
/// the alternation (`f = id`) every column is `(1 + P^δ) B e_x`, so on the members where `P^δ`
/// half-turns the contact's line every candidate's two storages vanish in the first-order chart and
/// the member is neutral for every class, and the least member decided on what remained past first
/// order (the regressions' record §8). On order-2 the antecedent's copy is anti-aligned with its
/// partner on those members and pays there what it gains on the others; the fit gains on every
/// member. No weight is set between the members or the two storages. Refused, typed, on a reading
/// alone whose lower end is not positive, or on two readings of different banks.
pub fn gain(pair: &TurnReading, alone: &TurnReading) -> Result<Growth, HnnError> {
    if pair.members.is_empty() || pair.members.len() != alone.members.len() {
        return Err(HnnError::NonpositiveDeclaration);
    }
    let mut joined = Growth {
        lower: Rat::one(),
        upper: Rat::one(),
    };
    for (p, a) in pair.members.iter().zip(&alone.members) {
        if !a.lower.is_positive() {
            return Err(HnnError::NonpositiveDeclaration);
        }
        joined.lower *= &p.lower / &a.upper;
        joined.upper *= &p.upper / &a.lower;
    }
    Ok(joined)
}

/// [definition; agent-inferred, September 30] **One refinement of the bank's lock iteration**
/// ([`bank_release`]): the section placed before it, every open candidate `(station, class)` in
/// station-major order with its reading, each open station's top class, the eligible stations
/// (the top's flip and lock both certified) with their gaps, and the stations it locked.
#[derive(Clone, Debug)]
pub struct BankRefinement<R> {
    pub placed: Vec<Option<usize>>,
    pub open: Vec<(usize, usize)>,
    pub read: Vec<R>,
    pub tops: Vec<(usize, usize)>,
    pub eligible: Vec<(usize, usize, Rat)>,
    pub locked: Vec<usize>,
}

/// [definition; agent-inferred, September 30] **A candidate's reading as the lock iteration reads
/// it**: its joint growth enclosure.
pub trait JointGrowth {
    /// The turn's reading.
    fn reading(&self) -> &TurnReading;
    /// Its joint growth enclosure.
    fn joint(&self) -> &Growth {
        &self.reading().joint
    }
}

impl JointGrowth for TurnReading {
    fn reading(&self) -> &TurnReading {
        self
    }
}

impl JointGrowth for TurnCovector {
    fn reading(&self) -> &TurnReading {
        &self.reading
    }
}

/// [definition; agent-inferred, September 29] **Generate a section by the receiving bank's locks**
/// (module header, "The bank reads the superposed passage"). The request's placement is fixed and
/// nothing is locked. In each refinement, for every unlocked station and every class of the
/// exterior chart, the receiving ring's storage is the request's placement with the locked data
/// and that candidate placed at their stations' residues, each datum at its transported weight
/// read from the candidate's station ([`BankPlacement::storage`]; the passage's one population at
/// modulus one), the other unlocked stations unplaced; the bank reads its turn
/// ([`ReceivingBank::read_turn`]). A station's reading is the lock's flip: its top candidate's joint
/// growth exceeds every other candidate's exactly ([`Growth::exceeds`], `θ = a/(a + K) > ½`) and the
/// bank locks there ([`Growth::is_locked`]); its gap is the top's `lower` less the largest other
/// `upper`, its upper end the top's `upper` less the largest other `lower`. Every station whose upper end
/// meets the largest positive gap locks (the readings do not order it below), its reading certified
/// ([`ReceivingBank::certify_turn`]); a locked datum is placed for the next refinement. It stops when
/// every station is locked, released at width zero through `receiver::release` (`section_release`),
/// or when no unlocked station has a positive gap, held with them plural, or when a lock's
/// Floquet certificate is refused, held with the open stations plural (the refusal named). Nothing
/// is deposited: the constitution is read at its cut (`E`, placed through the source port), and the
/// bank's members are declared. The readings of one refinement are co-present regions: shared
/// immutable input, one output each, so they run on the host's cores.
///
/// [definition; agent-inferred, October 5] **Where the material holds a pair contact closed**
/// ([`closed_pairs`], read at the placement from the material and the field's declared port), each
/// candidate's storage is its pair storage and its decision enclosure its gain on equal material
/// (module header, "The release reads the located pair on equal material";
/// [`BankPlacement::pair_storage`]); only the stations a closed contact joins to a placed crossing
/// are read in a refinement, and the bank locks on the pair storage's joint growth.
#[allow(clippy::too_many_arguments)]
pub fn generate_by_bank(
    field: &Field,
    constitution: &impl FieldMaterial,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    bank: &ReceivingBank,
    grain: u32,
) -> Result<BankGeneration, HnnError> {
    let ring = declared.ring;
    if !field.is_source(ring) {
        return Err(HnnError::MissingSourcePort { ring });
    }
    let placement = BankPlacement::of(field, constitution, current, moment, declared)?;
    let (generation, _) = bank_release(
        &placement,
        declared,
        field.alphabet(),
        bank,
        grain,
        |amplitudes| bank.read_turn(amplitudes, grain),
        false,
    )?;
    Ok(generation)
}

/// [definition; agent-inferred, September 30] **The bank's lock iteration, its one owner**
/// ([`generate_by_bank`]'s law; the retired comparison read it with each candidate's covector,
/// S2): every refinement reads every open candidate by `read`, decides each
/// open station's lock's flip and gap, locks together the stations not certified below the largest
/// positive gap,
/// certifies each lock's reading, and stops at the whole section, at a plural refinement, or at a
/// refused certificate. With `keep`, each refinement's readings are returned.
pub fn bank_release<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    bank_release_ordered(placement, declared, alphabet, bank, grain, read, keep, LockOrder::Gap)
}

/// [definition; agent-inferred, loop 1c's
/// [pin](../../../../research/records/2026-10-01_LOOP_1C_PERSISTENCE_REPRESENTATION_AND_REACH_PINNED_BEFORE_ITS_RUNS.md)
/// §2.4] **Which eligible stations a refinement locks.** The release's law is [`LockOrder::Gap`]:
/// the stations whose gap the readings do not certify below the largest, together (the field's
/// own order). The other two are
/// diagnostics of the release's order, never a law: among the same eligible stations (each top's
/// flip and lock certified, its gap positive) a refinement locks the one of least station index
/// ([`LockOrder::Ascending`], the receiving ring's clock direction from the request's last tick) or
/// of greatest ([`LockOrder::Descending`]), one lock a refinement. Eligibility, the readings, the
/// certificates and the stopping rules are the release's own under every order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LockOrder {
    /// The release's law: the stations not certified below the largest positive gap lock together.
    Gap,
    /// A diagnostic: the eligible station of least index locks alone.
    Ascending,
    /// A diagnostic: the eligible station of greatest index locks alone.
    Descending,
}

/// [definition; agent-inferred, October 2; its consequences proved-derived, formal-checked] **The
/// stations the readings do not certify below the largest gap** ([`LockOrder::Gap`]): each eligible station's gap is enclosed by its certain
/// gap `L_top − max_(x≠top) U_x` and its upper end `U_top − max_(x≠top) L_x`; a station locks when its
/// upper end meets the largest certain gap. The station of the largest certain gap always locks, so a
/// refinement with an eligible station locks one (Lean
/// `HNN/ExecutedComparison.certifiedLock_largest`); the true largest gap always locks
/// (`leader_locks`); a station that locks alone has the strictly largest true gap
/// (`lone_lock_is_largest`), so no move makes a station certified below another lock alone before it
/// unless their true gaps cross (`certified_order_needs_crossing`). On exact readings it is the
/// largest gap with its ties (`certifiedLock_exact`). The comparison's order term reads the same
/// two ends (the retired `hnn::executed::OrderTerm` at `9078f103`; `order_solved_locks_no_wrong`).
pub(crate) fn uncertified_largest(gaps: &[(usize, usize, Rat)], gap_uppers: &[Rat]) -> Vec<usize> {
    let largest = gaps.iter().map(|(_, _, gap)| gap).max();
    match largest {
        Some(largest) => gaps
            .iter()
            .zip(gap_uppers)
            .filter(|(_, gap_upper)| *gap_upper >= largest)
            .map(|(&(station, _, _), _)| station)
            .collect(),
        None => Vec::new(),
    }
}

/// **The bank's lock iteration under a declared order** ([`bank_release`] at [`LockOrder::Gap`];
/// the other orders are diagnostics of the release's order, [`LockOrder`]).
#[allow(clippy::too_many_arguments)]
pub fn bank_release_ordered<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
    order: LockOrder,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    release_iteration(placement, declared, alphabet, bank, grain, read, keep, order, None)
}

/// [measured-diagnostic; agent-inferred, October 1; the
/// [forced release's record](../../../../research/records/2026-10-01_THE_FORCED_RELEASE.md)]
/// **The forced release**: the release's own lock iteration under its own law ([`LockOrder::Gap`]:
/// which stations lock, from their own readings), each lock placed at its declared target class
/// instead of its top. Its refinements are the contexts the release would read had every earlier
/// lock been right: a comparison read there covers every decision the release faces along the
/// right trajectory, so if every one is solved the section is whole, lock by lock. A placed target
/// is a reading context, not a commit: its Floquet certificate is not read. Never a release law.
#[allow(clippy::too_many_arguments)]
pub fn bank_release_forced<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    targets: &[usize],
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    release_iteration(placement, declared, alphabet, bank, grain, read, true, LockOrder::Gap, Some(targets))
}

/// The lock iteration ([`bank_release_ordered`], [`bank_release_forced`]).
#[allow(clippy::too_many_arguments)]
fn release_iteration<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
    order: LockOrder,
    forced: Option<&[usize]>,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    use rayon::prelude::*;
    let stations = declared.stations;
    let mut locked: Vec<Option<usize>> = vec![None; stations];
    let mut tops: Vec<usize> = vec![declared.termination; stations];
    let mut locks: Vec<Vec<usize>> = Vec::new();
    let mut plural: Vec<usize> = Vec::new();
    let mut decisions = Vec::new();
    let mut kept = Vec::new();
    let mut uncertified = None;
    let (mut refinements, mut readings, mut certified, mut members) = (0, 0, 0, 0);
    let (mut ticks_closed, mut ticks) = (0, 0);
    // The pair contacts the material holds closed: with any, every candidate reads its own pair
    // storage against its own column alone (`BankPlacement::pair_storage`).
    let joined = !placement.contacts().is_empty();
    while locked.iter().any(Option::is_none) {
        let placed = locked.clone();
        // Each candidate reads the span from its own station (the station-framed law), or, where
        // the material carries pair contacts, the crossings its contacts join to it.
        let storage = |station: usize, class: usize| -> Vec<Rat> {
            if joined {
                let (pair, _) = placement
                    .pair_storage(station, class, &placed)
                    .expect("a station joined to a placed crossing");
                return pair;
            }
            let mut cells = placed.clone();
            cells[station] = Some(class);
            placement.storage(station, &cells)
        };
        let open: Vec<(usize, usize)> = (0..stations)
            .filter(|&station| locked[station].is_none())
            .filter(|&station| !joined || placement.joins(station, &placed))
            .flat_map(|station| (0..alphabet).map(move |class| (station, class)))
            .collect();
        let both: Vec<(R, Option<R>)> = open
            .par_iter()
            .map(|&(station, class)| {
                if joined {
                    let (pair, alone) = placement
                        .pair_storage(station, class, &placed)
                        .expect("a station joined to a placed crossing");
                    Ok((read(&turn(&pair))?, Some(read(&turn(&alone))?)))
                } else {
                    Ok((read(&turn(&storage(station, class)))?, None))
                }
            })
            .collect::<Result<Vec<_>, HnnError>>()?;
        // Each candidate's decision enclosure: its joint growth, or, on equal material, its gain
        // over its own column read alone.
        let decided: Vec<Growth> = both
            .iter()
            .map(|(reading, alone)| match alone {
                Some(alone) => gain(reading.reading(), alone.reading()),
                None => Ok(reading.joint().clone()),
            })
            .collect::<Result<Vec<_>, HnnError>>()?;
        refinements += 1;
        readings += both.iter().map(|(_, alone)| 1 + usize::from(alone.is_some())).sum::<usize>();
        let read: Vec<R> = both.into_iter().map(|(reading, _)| reading).collect();
        // Each unlocked station's lock's flip: its top candidate and its gap's enclosure, the
        // certain gap `L_top − max U` (the gap read) and its upper end `U_top − max L`.
        let mut gaps: Vec<(usize, usize, Rat)> = Vec::new();
        let mut gap_uppers: Vec<Rat> = Vec::new();
        let mut station_tops = Vec::new();
        for (index, chunk) in decided.chunks(alphabet).enumerate() {
            let station = open[index * alphabet].0;
            let best = (0..alphabet)
                .max_by(|&a, &b| chunk[a].lower.cmp(&chunk[b].lower).then(b.cmp(&a)))
                .expect("a class");
            tops[station] = best;
            station_tops.push((station, best));
            let top = &chunk[best];
            let runner = (0..alphabet)
                .filter(|&class| class != best)
                .map(|class| chunk[class].upper.clone())
                .max();
            let flips = (0..alphabet)
                .filter(|&class| class != best)
                .all(|class| top.exceeds(&chunk[class]));
            // The bank locks on the candidate's own storage: its joint growth past one.
            if flips && read[index * alphabet + best].joint().is_locked() {
                let gap = match &runner {
                    Some(runner) => &top.lower - runner,
                    None => top.lower.clone(),
                };
                let floor = (0..alphabet)
                    .filter(|&class| class != best)
                    .map(|class| chunk[class].lower.clone())
                    .max();
                let gap_upper = match &floor {
                    Some(floor) => &top.upper - floor,
                    None => top.upper.clone(),
                };
                gaps.push((station, best, gap));
                gap_uppers.push(gap_upper);
            }
        }
        let now: Vec<usize> = match order {
            LockOrder::Gap => uncertified_largest(&gaps, &gap_uppers),
            LockOrder::Ascending => gaps.iter().map(|&(station, _, _)| station).min().into_iter().collect(),
            LockOrder::Descending => gaps.iter().map(|&(station, _, _)| station).max().into_iter().collect(),
        };
        let mut taken = Vec::new();
        for &station in &now {
            let class = forced.map_or(tops[station], |targets| targets[station]);
            let index = open
                .iter()
                .position(|&pair| pair == (station, class))
                .expect("a read candidate");
            let reading = decided[index].clone();
            let amplitudes = turn(&storage(station, class));
            let certificate = if forced.is_some() {
                Ok(None)
            } else {
                bank.certify_turn(&amplitudes, read[index].reading(), grain).map(Some)
            };
            match certificate {
                Ok(None) => {}
                Ok(Some(certificate)) => {
                    certified += certificate.certificates.len();
                    ticks_closed += certificate.closed;
                    ticks += certificate.ticks;
                }
                // A refused certificate refuses the lock and the release: with the reading's upper
                // end strictly outside every multiplier, the exact Stein solve of the exact
                // monodromy always certifies, so a refusal can only mean the reading itself is
                // wrong.
                Err(HnnError::UncertifiedFloquet { .. }) => {
                    uncertified = Some((station, class));
                    break;
                }
                Err(error) => return Err(error),
            }
            members += bank.pumps().len();
            let runner = (0..alphabet)
                .filter(|&other| other != class)
                .map(|other| decided[index - class + other].clone())
                .max_by(|a, b| a.upper.cmp(&b.upper))
                .expect("a runner-up");
            decisions.push((station, class, reading, runner));
            locked[station] = Some(class);
            taken.push(station);
        }
        let stop = now.is_empty() || uncertified.is_some();
        if stop {
            plural = (0..stations)
                .filter(|&station| locked[station].is_none())
                .collect();
            if let Some((station, _)) = uncertified {
                plural.retain(|&s| s != station);
                plural.insert(0, station);
            }
        }
        if keep {
            kept.push(BankRefinement {
                placed: placed.clone(),
                open,
                read,
                tops: station_tops,
                eligible: gaps,
                locked: taken.clone(),
            });
        }
        if !taken.is_empty() {
            locks.push(taken);
        }
        if stop {
            break;
        }
    }
    let classes: Vec<usize> = locked
        .iter()
        .zip(&tops)
        .map(|(lock, &top)| lock.unwrap_or(top))
        .collect();
    Ok((
        BankGeneration {
            release: section_release(declared, classes, plural)?,
            refinements,
            locks,
            readings,
            certified,
            members,
            ticks_closed,
            ticks,
            decisions,
            uncertified,
            contacts: placement.contacts().to_vec(),
        },
        kept,
    ))
}

/// [definition; agent-inferred, September 29; the passage law, September 30; the station-framed
/// law, September 30] **The receiving ring's storage under the passage, read from a station**
/// ([`generate_by_bank`]; module header, "The section continues the request's passage"): each
/// occupied phase's read of the request's raw counts `P^(λ−c) E M[c]` on the receiving ring, the
/// pair ports' normalized read, and, per station `j` and class `x`, the datum's image
/// `P^(λ − c_j) E e_x`, `c_j = τ + 1 + j` (mod `d`). A candidate at station `j` reads the span, the
/// request and the section's cells `S`, as one field, each datum weighed by its two-sided transport
/// distance from `j`:
///
/// ```text
/// z_j(S) = z_pairs + Σ_c w_j(c) P^(λ−c) E M[c] + Σ_(i∈S) w_j(i) P^(λ − c_i) E e_(x_i)
/// w_j(k) = chart(ρ^(r_j(k)) / (Σ_c n(c) ρ^(r_j(c)) + Σ_(i∈S) ρ^(r_j(i))))
/// r_j(c) = 1 + j + ((τ − c) mod d)   (a request phase),   r_j(i) = |i − j|   (a station)
/// ```
///
/// with `ρ` the navigator's transport modulus: at `ρ = 1` every datum weighs `ν̂(n + |S|)`, in
/// every frame. **Why two-sided** [agent-inferred, the
/// [re-entry diagnosis](../../../../research/records/2026-09-30_THE_RE_ENTRY_DIAGNOSED_A_LATER_LOCK_TAKES_THE_SPANS_MASS_AND_QUENCHES_THE_EARLIER_STATIONS.md)
/// §6]: the section is a joint field, refined whole, not a stream read in time order, so the
/// reading at station `j` is the dissipative tube's stationary response to each datum, which
/// falls by `ρ` a tick in both directions of the tube (the tube's pairing reading, `ρ^|Δ|`, the
/// stationary covariance of a transport of modulus `ρ` a tick); the one-way dilation
/// `ρ^(τ_end − τ_k)` read at the span's end grows backward from `j`, so a lock `r` ticks after `j`
/// weighed `ρ^(−r)` times `j`'s own candidate and took the span's mass (the diagnosis measured up to
/// `[205/256, 103/128]` of it from station 0). Read from `j`:
/// - **on data no later than `j` it is the one-way law exactly** (the common factor `ρ^(τ_end − τ_j)`
///   cancels in the normalization; Lean `HNN/IndexedOpen.framed_weight_one_sided`), so the open
///   section, which holds only the request and the candidate, reads as before, and so does a
///   station read after every lock;
/// - **a datum `r ≥ 1` ticks from `j` weighs at most `ρ^r`** of `j`'s span, the candidate's own
///   datum weighing one before the normalization (`framed_weight_le_pow`), so a far lock no longer
///   quenches an earlier station;
/// - **every datum enters**, none is dropped by its distance or the span's length, and each
///   station's normalization is its own systolic reduction over the same carried powers `ρ^r`;
/// - **every modality reads it the same way**: the law reads only the distance between two ticks
///   of the ring's clock; a text cell, an image pixel at its scan tick (its row neighbours at
///   distance one on either side, the pixels one row away at the row's width), an acoustic sample
///   at its sample tick, a motor screw at its step.
///
/// The request's reads are kept once and every candidate is read without re-encoding the request;
/// held to the explicit two-sided formula exactly by the owner's tests, and to the continued
/// passage's open ([`SourceMoment::continued`], read at the span's last datum) exactly when no
/// placed datum lies after the station read. With nothing placed it is the request's own open.
#[derive(Clone, Debug)]
pub struct BankPlacement {
    /// Each occupied request phase: its lag `(τ − c) mod d` behind the request's last tick, its
    /// count and its read.
    reads: Vec<(u64, u64, Vec<Rat>)>,
    pairs: Vec<Rat>,
    images: Vec<Vec<Vec<Rat>>>,
    chart: PopulationChart,
    modulus: Rat,
    stations: u64,
    /// `ρ^r` for every distance `r < d + m`.
    powers: Vec<Rat>,
    population: u64,
    /// The receiving ring's period `d`.
    period: u64,
    /// The distances at which the source port holds a pair contact closed ([`closed_pairs`]).
    contacts: Vec<usize>,
}

impl BankPlacement {
    /// The request's reads and every station's class images on the receiving ring. Refused, at a
    /// transport below modulus one, when the request and its declared stations span more than one
    /// turn ([`HnnError::AliasedAges`]).
    pub fn of(
        field: &Field,
        constitution: &impl FieldMaterial,
        current: &Current,
        moment: &SourceMoment,
        declared: &Refinement,
    ) -> Result<Self, HnnError> {
        let ring = declared.ring;
        let port = constitution
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let geometry = field.ring(ring);
        let period = geometry.period();
        let modulus = constitution.transport(ring);
        let stations = declared.stations as u64;
        // The span's check: the moment read over its declared stations (every station placed).
        let full = moment.continued(field, current, ring, &vec![Some(0); declared.stations])?;
        full.phase_weights(field, ring, &modulus)?;
        let (raw, pairs) = moment.open_parts(field, constitution, current, ring)?;
        let phase = current.phase(field, ring)?;
        let reads = raw
            .into_iter()
            .map(|(c, read)| -> Result<(u64, u64, Vec<Rat>), HnnError> {
                let c = c as u64;
                let lag = (phase + period - c) % period;
                let count: u64 = moment.phase_counts(ring, c as usize)?.iter().sum();
                Ok((lag, count, read))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let lift = current.lift()[ring].clone();
        let columns: Vec<Vec<Rat>> = (0..field.alphabet())
            .map(|class| {
                (0..port.rows())
                    .map(|row| port.get(row, class).cloned())
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()?;
        let images = (0..declared.stations)
            .map(|station| {
                let residue = (phase + 1 + station as u64) % period;
                let rotation = &lift - BigInt::from(residue);
                columns
                    .iter()
                    .map(|column| geometry.rotate(column, &rotation))
                    .collect()
            })
            .collect();
        let mut powers = Vec::with_capacity((period + stations) as usize);
        let mut power = Rat::one();
        for _ in 0..period + stations {
            powers.push(power.clone());
            power *= &modulus;
        }
        Ok(Self {
            reads,
            pairs,
            images,
            chart: PopulationChart::of(field),
            modulus,
            stations,
            powers,
            population: moment.population(ring)?,
            period,
            contacts: closed_pairs(field, constitution, ring)?,
        })
    }

    /// The navigator's transport modulus the placement weighs at.
    pub fn modulus(&self) -> &Rat {
        &self.modulus
    }

    /// **The pair contacts the release reads**: the distances `δ` at which the source port holds a
    /// pair contact closed ([`closed_pairs`]), read from the material at the placement; empty on a
    /// port that carries no located pair.
    pub fn contacts(&self) -> &[usize] {
        &self.contacts
    }

    /// Whether a residue lies `δ` ticks from another on the receiving ring, either way round, for
    /// a closed contact's `δ`: `r ≡ ±δ (mod d)`.
    fn contact_distance(&self, distance: u64) -> bool {
        let r = distance % self.period;
        self.contacts.iter().any(|&delta| {
            let delta = delta as u64 % self.period;
            r == delta || r == (self.period - delta) % self.period
        })
    }

    /// **The crossings a closed pair contact joins to station `j`**: every request phase and every
    /// placed station whose residue lies `δ` ticks from `c_j`, either way round, for each closed
    /// contact's `δ`; each with its count and its read (a request phase's raw counts read, a
    /// station's class image).
    fn partners<'a>(&'a self, station: usize, cells: &[Option<usize>]) -> Vec<(u64, &'a Vec<Rat>)> {
        let mut partners: Vec<(u64, &Vec<Rat>)> = self
            .reads
            .iter()
            .filter(|(lag, _, _)| self.contact_distance(Self::request_distance(station, *lag)))
            .map(|(_, count, read)| (*count, read))
            .collect();
        for (placed, cell) in cells.iter().enumerate() {
            if let Some(class) = cell
                && placed != station
                && self.contact_distance(Self::station_distance(station, placed))
            {
                partners.push((1, &self.images[placed][*class]));
            }
        }
        partners
    }

    /// Whether a closed pair contact joins station `j` to a placed crossing ([`BankPlacement::partners`]).
    pub fn joins(&self, station: usize, cells: &[Option<usize>]) -> bool {
        !self.partners(station, cells).is_empty()
    }

    /// [definition; agent-inferred, October 5; lane C's
    /// [record](../../../../research/records/2026-10-05_THE_RELEASE_READS_THE_LOCATED_PAIR_ON_EQUAL_MATERIAL.md)]
    /// **A candidate's pair storage and its own column alone, on equal material.** The candidate
    /// `x` at station `j` and the crossings the source port's closed pair contacts join to it
    /// ([`BankPlacement::partners`]: residues `c_j ± δ`, from the request or from the section's
    /// locked stations), as one population at the contact's own weight. The contact's channel is the
    /// turn the deposit carried, `U = P^δ` (`(E − B) T = P^δ B`): a rotation of the ring, a mode of
    /// modulus one, stored and carried without loss. So the partner is read through it without the
    /// tube's contraction `ρ^δ`, which every datum of the span takes alike (one scalar modulus a
    /// ring) and which made the nearest lock outweigh the pair; no weight is chosen, and none is cut
    /// off,
    ///
    /// ```text
    /// z_pair(j, x) = ν̂(N) ( P^(λ−c_j) E e_x + Σ_(p joined to j) P^(λ−c_p) E M[p] ),   N = 1 + Σ_p n(p)
    /// z_alone(j, x) = ν̂(N) P^(λ−c_j) E e_x
    /// ```
    ///
    /// With `(E − B) e_x = P^δ B e_y` (the deposit's consumer, `hnn::executed::pair_deposit`), a
    /// candidate that fits the contact carries, at its antecedent's placement, the antecedent's
    /// prior image a second time, `P^(λ−c_j) (E − B) e_x = P^(λ−c_(j−δ)) B e_y`: the two add
    /// coherently. The release compares the bank's reading of `z_pair` against the same bank's
    /// reading of `z_alone` (the gain), so a class's own column, whatever its resonance power,
    /// enters both and only what the contact adds decides. `None` when no closed contact joins `j`
    /// to a placed crossing: the station waits for its antecedent (or its consequence) to lock.
    /// Every modality reads it the same way: a contact joins two ticks of the ring's clock.
    pub fn pair_storage(
        &self,
        station: usize,
        class: usize,
        cells: &[Option<usize>],
    ) -> Option<(Vec<Rat>, Vec<Rat>)> {
        let partners = self.partners(station, cells);
        if partners.is_empty() {
            return None;
        }
        let population = 1 + partners.iter().map(|(count, _)| count).sum::<u64>();
        let nu = self.chart.value(population);
        let own = &self.images[station][class];
        let alone: Vec<Rat> = own.iter().map(|x| x * &nu).collect();
        let mut pair = own.clone();
        for (_, read) in &partners {
            for (value, add) in pair.iter_mut().zip(read.iter()) {
                *value += add;
            }
        }
        Some((pair.iter().map(|x| x * &nu).collect(), alone))
    }

    /// The declared stations `m`.
    pub fn stations(&self) -> usize {
        self.stations as usize
    }

    /// **A request phase's distance from the station read**: `1 + j + lag`, the ticks from the
    /// phase's last crossing to station `j`'s.
    fn request_distance(station: usize, lag: u64) -> u64 {
        1 + station as u64 + lag
    }

    /// **A placed station's distance from the station read**: `|i − j|`, on either side.
    fn station_distance(station: usize, placed: usize) -> u64 {
        station.abs_diff(placed) as u64
    }

    /// Every datum of the span read from `station`: its distance, its count and its read (the
    /// request's phases, then the placed stations in order).
    fn data<'a>(
        &'a self,
        station: usize,
        cells: &[Option<usize>],
    ) -> Vec<(u64, Rat, &'a Vec<Rat>)> {
        assert!(station < self.stations(), "the station read is a declared station");
        let mut data: Vec<(u64, Rat, &Vec<Rat>)> = self
            .reads
            .iter()
            .map(|(lag, count, read)| {
                (
                    Self::request_distance(station, *lag),
                    Rat::from_integer(BigInt::from(*count)),
                    read,
                )
            })
            .collect();
        for (placed, cell) in cells.iter().enumerate() {
            if let Some(class) = cell {
                data.push((
                    Self::station_distance(station, placed),
                    Rat::one(),
                    &self.images[placed][*class],
                ));
            }
        }
        data
    }

    /// The span's transported mass read from `station`,
    /// `Σ_c n(c) ρ^(r_j(c)) + Σ_(i∈S) ρ^(|i − j|)`, exactly.
    fn mass(&self, station: usize, cells: &[Option<usize>]) -> Rat {
        self.data(station, cells)
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum()
    }

    /// **The passage's weights read from a station**: each request phase's and each placed
    /// station's `w_j`, on the population chart; at `ρ = 1` all `ν̂(n + |S|)`, in every frame.
    #[allow(clippy::type_complexity)]
    pub fn weights(&self, station: usize, cells: &[Option<usize>]) -> (Vec<Rat>, Vec<Option<Rat>>) {
        self.weights_over(station, cells, cells)
    }

    /// The weights of the data `cells` read from `station`, normalized over the span `mass` places
    /// (the request's phases and the stations `mass` places; only which stations are placed counts,
    /// never their classes). At `mass = cells` it is [`BankPlacement::weights`].
    #[allow(clippy::type_complexity)]
    fn weights_over(
        &self,
        station: usize,
        cells: &[Option<usize>],
        mass: &[Option<usize>],
    ) -> (Vec<Rat>, Vec<Option<Rat>>) {
        assert!(station < self.stations(), "the station read is a declared station");
        if self.modulus.is_one() {
            let placed = mass.iter().filter(|cell| cell.is_some()).count() as u64;
            let nu = self.chart.value(self.population + placed);
            return (
                vec![nu.clone(); self.reads.len()],
                cells.iter().map(|cell| cell.map(|_| nu.clone())).collect(),
            );
        }
        let mass = self.mass(station, mass);
        let weigh = |distance: u64| self.chart.chart(&(&self.powers[distance as usize] / &mass));
        (
            self.reads
                .iter()
                .map(|(lag, _, _)| weigh(Self::request_distance(station, *lag)))
                .collect(),
            cells
                .iter()
                .enumerate()
                .map(|(placed, cell)| cell.map(|_| weigh(Self::station_distance(station, placed))))
                .collect(),
        )
    }

    /// **The receiving ring's storage read from a station** with the section's cells placed (a
    /// station's class, or unplaced): the pair ports' read plus every datum of the passage at its
    /// transported weight from `station`.
    pub fn storage(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        self.storage_over(station, cells, cells)
    }

    /// [measured-diagnostic; agent-inferred, loop 1c's
    /// [pin](../../../../research/records/2026-10-01_LOOP_1C_PERSISTENCE_REPRESENTATION_AND_REACH_PINNED_BEFORE_ITS_RUNS.md)
    /// §2.3; a diagnostic, never a law] **The storage read from a station with its normalization
    /// taken over another span**: the data `cells` enter (the request's phases and the stations
    /// `cells` places, the candidate's own among them), each at its transported weight from `station`
    /// over the mass of the span `mass` places, `chart(ρ^(r(k)) / M_j(mass))`. At `mass = cells` it is
    /// [`BankPlacement::storage`] exactly. A later lock `k` landing on a section `S` read from `j`
    /// splits into two parts (Lean `HNN/IndexedOpen.transported_weight_insert`): **the
    /// normalization**, every earlier datum's weight scaled by `M_j(S)/M_j(S ∪ k)` (the span's mass
    /// taken by `k`; `storage_over(j, S, S ∪ k)`), and **the entry**, `k`'s own image at its weight
    /// (`storage_over(j, S ∪ k, S)` adds it over the earlier mass). On the chart, with one mass the
    /// common data read one weight, so `storage(j, S ∪ k) − storage_over(j, S, S ∪ k)` and
    /// `storage_over(j, S ∪ k, S) − storage(j, S)` are each exactly `k`'s entry (the owner's test).
    pub fn storage_over(
        &self,
        station: usize,
        cells: &[Option<usize>],
        mass: &[Option<usize>],
    ) -> Vec<Rat> {
        let (request, section) = self.weights_over(station, cells, mass);
        let mut storage = self.pairs.clone();
        for ((_, _, read), weight) in self.reads.iter().zip(&request) {
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * weight;
            }
        }
        for (placed, (cell, weight)) in cells.iter().zip(&section).enumerate() {
            if let (Some(class), Some(weight)) = (cell, weight) {
                for (value, add) in storage.iter_mut().zip(&self.images[placed][*class]) {
                    *value += add * weight;
                }
            }
        }
        storage
    }

    /// The storage's derivative in the modulus rebuilt from each datum's reach slope,
    /// `Σ_k (ρ^(r_k)/M) s_k read_k` ([`BankPlacement::reach_slopes`] against
    /// [`BankPlacement::modulus_derivative`], the owner's test).
    #[cfg(test)]
    pub(crate) fn reach_derivative(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        let mass = self.mass(station, cells);
        let (request, section) = self.reach_slopes(station, cells);
        let mut derivative = vec![Rat::zero(); self.pairs.len()];
        let mut add = |distance: u64, slope: &Rat, read: &[Rat]| {
            let factor = &self.powers[distance as usize] / &mass * slope;
            for (value, x) in derivative.iter_mut().zip(read) {
                *value += x * &factor;
            }
        };
        for ((lag, _, read), slope) in self.reads.iter().zip(&request) {
            add(Self::request_distance(station, *lag), slope, read);
        }
        for (placed, (cell, slope)) in cells.iter().zip(&section).enumerate() {
            if let (Some(class), Some(slope)) = (cell, slope) {
                add(Self::station_distance(station, placed), slope, &self.images[placed][*class]);
            }
        }
        derivative
    }

    /// The storage read from a station at the exact transported weights at a modulus (no chart):
    /// the test's reference for [`BankPlacement::modulus_derivative`].
    #[cfg(test)]
    pub(crate) fn exact_storage(
        &self,
        station: usize,
        cells: &[Option<usize>],
        modulus: &Rat,
    ) -> Vec<Rat> {
        let power = |distance: u64| crate::hnn::moment::modulus_power(modulus, distance);
        let data = self.data(station, cells);
        let mass: Rat = data.iter().map(|(distance, count, _)| power(*distance) * count).sum();
        let mut storage = self.pairs.clone();
        for (distance, _, read) in data {
            let weight = power(distance) / &mass;
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * &weight;
            }
        }
        storage
    }

    /// [definition; agent-inferred, September 30] **The storage's derivative in the transport
    /// modulus**, read from a station, at the exact weights `w_k = ρ^(r_k)/mass`:
    /// `∂w_k/∂ρ = w_k (r_k − r̄)/ρ`, `r_k` the datum's distance from the station read and `r̄` the
    /// span's weighted mean distance, so `∂z/∂ρ = Σ_k ∂w_k/∂ρ · (datum k's read)`; the modulus's
    /// covector paired with it in the retired descent move (`hnn::executed` at `9078f103`, "The
    /// committed move"). The one-way law's form with
    /// each age replaced by the distance from the station read.
    pub fn modulus_derivative(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        let data = self.data(station, cells);
        let mass: Rat = data
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum();
        let mean: Rat = data
            .iter()
            .map(|(distance, count, _)| {
                &self.powers[*distance as usize] * count * Rat::from_integer(BigInt::from(*distance))
            })
            .sum::<Rat>()
            / &mass;
        // [agent-inferred, October 1] Each datum's slope and each product are held at
        // `DERIVATIVE_BITS` significant bits toward zero: the exact entries carry the transported
        // mass's denominators (powers of `ρ` over thousands of bits), and the exact products cost
        // 603,039 ms of a 635,681 ms forced read at the opening. Every consumer already reads the
        // derivative at a grain (the joint direction at `JOINT_BITS`, the witness's `δ` at 128 bits).
        let held = |x: Rat| -> Rat {
            if x.is_zero() {
                x
            } else if x.is_negative() {
                -crate::holon::deposition::significant(&-x, DERIVATIVE_BITS, false)
            } else {
                crate::holon::deposition::significant(&x, DERIVATIVE_BITS, false)
            }
        };
        let mut derivative = vec![Rat::zero(); self.pairs.len()];
        for (distance, _, read) in data {
            let weight = &self.powers[distance as usize] / &mass;
            let slope =
                held(weight * (Rat::from_integer(BigInt::from(distance)) - &mean) / &self.modulus);
            if slope.is_zero() {
                continue;
            }
            for (value, add) in derivative.iter_mut().zip(read) {
                *value += held(add * &slope);
            }
        }
        derivative
    }

    /// [definition; agent-inferred, October 2; the
    /// [joined move's record](../../../../research/records/2026-10-02_THE_TRANSPORT_MODULUS_JOINS_THE_RECEIVERS_MINIMUM_ENERGY_MOVE.md)]
    /// **Each datum's reach slope** read from a station, aligned with [`BankPlacement::weights`]:
    /// `s_k = (r_k − r̄)/ρ`, the log-derivative of datum `k`'s transported weight in the modulus,
    /// `∂w_k/∂ρ = w_k s_k` (the factor [`BankPlacement::modulus_derivative`] applies), with `r̄` the
    /// span's weighted mean distance at the exact weights. Each slope is held at the derivative's
    /// grain. The request's phases come first, then the placed stations (`None` where unplaced).
    #[allow(clippy::type_complexity)]
    pub fn reach_slopes(
        &self,
        station: usize,
        cells: &[Option<usize>],
    ) -> (Vec<Rat>, Vec<Option<Rat>>) {
        let data = self.data(station, cells);
        let mass: Rat = data
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum();
        let mean: Rat = data
            .iter()
            .map(|(distance, count, _)| {
                &self.powers[*distance as usize] * count * Rat::from_integer(BigInt::from(*distance))
            })
            .sum::<Rat>()
            / &mass;
        let slope = |distance: u64| -> Rat {
            let x = (Rat::from_integer(BigInt::from(distance)) - &mean) / &self.modulus;
            if x.is_zero() {
                x
            } else if x.is_negative() {
                -crate::holon::deposition::significant(&-x, DERIVATIVE_BITS, false)
            } else {
                crate::holon::deposition::significant(&x, DERIVATIVE_BITS, false)
            }
        };
        (
            self.reads
                .iter()
                .map(|(lag, _, _)| slope(Self::request_distance(station, *lag)))
                .collect(),
            cells
                .iter()
                .enumerate()
                .map(|(placed, cell)| cell.map(|_| slope(Self::station_distance(station, placed))))
                .collect(),
        )
    }
}

/// The significant bits a storage derivative in `ρ` is held at ([`BankPlacement::modulus_derivative`]):
/// above every consumer's own grain (`JOINT_BITS = 128` in the joint direction, the witness's `δ` at
/// 128 bits).
const DERIVATIVE_BITS: u32 = 192;

/// [definition; agent-inferred, October 5; lane C's
/// [record](../../../../research/records/2026-10-05_THE_RELEASE_READS_THE_LOCATED_PAIR_ON_EQUAL_MATERIAL.md)]
/// **The pair contacts the source port holds closed**: the distances `δ ∈ [1, d)` of the receiving
/// ring at which some pair contact `y → x` has zero slip, `P^δ B e_y − (E − B) e_x = 0` with
/// `B e_y ≠ 0` (`hnn::executed::pair_slip`), `E` the material's source port and `B` the field's
/// declared one (`hnn::constitution::declared_source_port`). It is the located pair's deposit read
/// back from the material: the key's distance is read where its deposit left it, never declared by
/// the caller, and a port that carries no located pair (every opening) closes none. Only the
/// distance is read: which class follows which stays in `E`'s columns, where the bank's reading of
/// each candidate's pair storage meets it ([`BankPlacement::pair_storage`]). The closure is exact:
/// a later deposit that moves a located column opens its contact again.
pub fn closed_pairs(
    field: &Field,
    material: &impl FieldMaterial,
    ring: usize,
) -> Result<Vec<usize>, HnnError> {
    let Some(prior) = crate::hnn::constitution::declared_source_port(field, ring)? else {
        return Ok(Vec::new());
    };
    let port = material
        .source_port(ring)
        .ok_or(HnnError::MissingSourcePort { ring })?;
    if port.rows() != prior.rows() || port.columns() != prior.columns() {
        return Err(HnnError::Shape {
            what: "the source port against its declared prior",
            expected: prior.rows() * prior.columns(),
            found: port.rows() * port.columns(),
        });
    }
    let alphabet = field.alphabet();
    let column = |matrix: &crate::ratio::linear::ExactRatMatrix, class: usize| -> Result<Vec<Rat>, HnnError> {
        (0..matrix.rows())
            .map(|row| Ok(matrix.get(row, class)?.clone()))
            .collect()
    };
    // The classes whose column carries a learned part, and the prior's nonzero columns.
    let mut learned = Vec::new();
    for class in 0..alphabet {
        if column(port, class)? != column(&prior, class)? {
            learned.push(class);
        }
    }
    let mut antecedents = Vec::new();
    for class in 0..alphabet {
        if column(&prior, class)?.iter().any(|x| !x.is_zero()) {
            antecedents.push(class);
        }
    }
    let period = field.ring(ring).period() as usize;
    let mut closed = Vec::new();
    for offset in 1..period {
        let mut found = false;
        'pairs: for &x in &learned {
            for &y in &antecedents {
                let slip = crate::hnn::executed::pair_slip(field, ring, port, &prior, offset, (y, x))?;
                if slip.iter().all(Zero::is_zero) {
                    found = true;
                    break 'pairs;
                }
            }
        }
        if found {
            closed.push(offset);
        }
    }
    Ok(closed)
}

// -------------------------------------------------------------------------------------------
// the physical repair

/// [definition; agent-inferred, October 5; lane C's physical repair, module header "The physical
/// repair"] **A damaged section as the field reads it**: the admitted encoded intact runs, each at
/// its declared station (its first cell's placement on the section's clock), over a declared
/// section of `length` stations and the encoding's `classes`. An erased station holds nothing: no
/// class, no clock step and no count. The section holds no erased class, so no truth of an erased
/// cell can reach the forward consumer ([`repair_by_field`]), and the reference repair's families
/// stay outside it (the grader's).
#[derive(Clone, Debug, PartialEq)]
pub struct DamagedSection {
    length: usize,
    classes: usize,
    runs: Vec<(usize, Encoded)>,
}

impl DamagedSection {
    /// **The damage**: an encoded passage with its erased cells dropped, cut into its intact runs
    /// (`Encoded::part`, each keeping the encoding that produced it). It is the transition that
    /// drops the erased cells, so their classes leave with it. Refused with an erasure past the
    /// passage.
    pub fn damage(encoded: &Encoded, erased: &[usize]) -> Result<Self, HnnError> {
        let length = encoded.len();
        if let Some(&t) = erased.iter().find(|&&t| t >= length) {
            return Err(HnnError::Shape {
                what: "an erasure within the passage",
                expected: length,
                found: t,
            });
        }
        let mut runs = Vec::new();
        let mut t = 0;
        while t < length {
            if erased.contains(&t) {
                t += 1;
                continue;
            }
            let start = t;
            while t < length && !erased.contains(&t) {
                t += 1;
            }
            runs.push((start, encoded.part(start..t)?));
        }
        Self::of_runs(length, encoded.classes(), runs)
    }

    /// **Intact runs at declared stations** over a section of `length` stations on `classes`
    /// classes: refused when a run is empty, overlaps another, lies past the section, or was encoded
    /// on another class count.
    pub fn of_runs(
        length: usize,
        classes: usize,
        mut runs: Vec<(usize, Encoded)>,
    ) -> Result<Self, HnnError> {
        runs.sort_by_key(|(start, _)| *start);
        let mut end = 0;
        for (start, run) in &runs {
            if run.is_empty() || *start < end || start + run.len() > length {
                return Err(HnnError::Shape {
                    what: "intact runs, nonempty and disjoint, within the section",
                    expected: length,
                    found: start + run.len(),
                });
            }
            if run.classes() != classes {
                return Err(HnnError::Shape {
                    what: "an intact run on the section's classes",
                    expected: classes,
                    found: run.classes(),
                });
            }
            end = start + run.len();
        }
        Ok(Self {
            length,
            classes,
            runs,
        })
    }

    /// The declared stations `L`.
    pub fn length(&self) -> usize {
        self.length
    }

    /// The encoding's classes.
    pub fn classes(&self) -> usize {
        self.classes
    }

    /// The intact runs, each at its first station.
    pub fn runs(&self) -> &[(usize, Encoded)] {
        &self.runs
    }

    /// **The declared chart**: each intact station's class, `None` at each erasure.
    pub fn placed(&self) -> Vec<Option<usize>> {
        let mut cells = vec![None; self.length];
        for (start, run) in &self.runs {
            for (k, class) in run.classes_read().enumerate() {
                cells[start + k] = Some(class);
            }
        }
        cells
    }

    /// The erased stations, in order.
    pub fn erased(&self) -> Vec<usize> {
        self.placed()
            .iter()
            .enumerate()
            .filter_map(|(t, cell)| cell.is_none().then_some(t))
            .collect()
    }
}

/// [definition; agent-inferred, October 5] **One station's read at its bound crossing**: the
/// station `j`, the local crossing that reads it (`e = e_0 + j`, the receiver's phase `j`:
/// `hnn::receiving`, "The receiver reads the passage by epochs"), the refinement clock's tick there
/// (`opened_at + e`), and the read `R · P_R^(τ_R) v_R(e)` at the receiver's grain
/// ([`ReceivingPhases::read`]).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StationRead {
    pub station: usize,
    pub crossing: usize,
    pub tick: usize,
    pub read: ReceivingRead,
}

impl StationRead {
    /// **The point reading's leading classes at the grain**: the classes whose grain cell
    /// `(carry, phase class)` is the largest. A reading of one executed state, never a fibre: a
    /// point reading does not certify the domain of the coupled drive, so no release reads it.
    pub fn leaders(&self) -> Vec<usize> {
        let cells = &self.read.cells;
        let Some(top) = cells.iter().map(|cell| (&cell.carry, cell.phase)).max() else {
            return Vec::new();
        };
        cells
            .iter()
            .enumerate()
            .filter(|(_, cell)| (&cell.carry, cell.phase) == top)
            .map(|(class, _)| class)
            .collect()
    }
}

/// [definition] **Why an erased station is held.**
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Unresolved {
    /// No crossing of the declared receiving section reads the station.
    Unread,
    /// A crossing reads it, but no owner certifies the domain of the word's coupled drive that the
    /// decoder would project (#62), so the domain is the whole state space.
    UncertifiedDomain,
}

/// [definition] **One station after the physical repair**: intact as admitted, released at width
/// zero, or held with its fibre and the reason it is unresolved.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RepairedCell {
    Intact(usize),
    Released(usize),
    Held {
        fibre: Vec<usize>,
        unresolved: Unresolved,
    },
}

impl RepairedCell {
    /// The station's class, when it has one.
    pub fn class(&self) -> Option<usize> {
        match self {
            Self::Intact(class) | Self::Released(class) => Some(*class),
            Self::Held { .. } => None,
        }
    }
}

/// [definition] **The physical repair's return**: each station's cell, each bound station's read,
/// the source opening's work receipt, every executed full tick's field balance, the word's balance
/// and the carried end at its last crossing ([`Word::reception_end`]). The word itself, its
/// per-tick passage and its waves, is dropped inside [`repair_by_field`] once read.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PhysicalRepair {
    pub cells: Vec<RepairedCell>,
    pub reads: Vec<StationRead>,
    pub opening: SourceOpeningReceipt,
    pub balances: Vec<FieldBalance>,
    pub word: WordBalance,
    pub carry: ReceptionCarry,
}

/// **Repair a damaged section by the field's own motion** (module header, "The physical repair"):
/// the admitted intact runs placed on the declared chart as one sparse source moment, imposed once
/// at the word's opening ([`Word::open_exact_received`]), the one continuing word run through the
/// declared receiver's crossings ([`Word::forward`]), each bound station read through the field's
/// decoder at its grain ([`ReceivingPhases::read`], material alone), and each erased station
/// decided by `receiver::release` at tolerance zero over the classes its domain's projection
/// admits. Refused when a run is not admitted (`Field::admit`), when the opening's work does not
/// close, or when the executed crossings are not the declared section's clock.
pub fn repair_by_field(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
) -> Result<PhysicalRepair, HnnError> {
    for (_, run) in &section.runs {
        field.admit(run)?;
    }
    // The declared chart: station j at τ_g + 1 + j on every source ring, the erasures unplaced.
    let placed = section.placed();
    let mut source = SourceMoment::open_with(field, current, material)?;
    for &ring in field.sources() {
        source = source.continued(field, current, ring, &placed)?;
    }
    // One accounted imposition, then the one continuing word through the declared crossings.
    let (mut word, opening_receipt) =
        Word::open_exact_received(field, material, current, &source, opening)?;
    let anchors = word.forward(phases)?;
    let balances = word.field_balances().to_vec();
    let carry = word.reception_end()?;
    let balance = WordBalance::of(&word.released()?);
    let opened_at = word.opened_at();
    // The clock certificate: the carried end stands at the last declared crossing's tick and the
    // word's own hop clock, which counts the crossings scattered, one past it, so crossing e is
    // the refinement's tick opened_at + e (the placement alone certifies no clock).
    let last = opened_at + phases.last_epoch();
    if carry.ticks != last
        || word.clock().ticks() != num_bigint::BigUint::from(last + 1)
        || anchors.len() != phases.aperture()
    {
        return Err(HnnError::ContinuingState {
            what: "the executed crossings are not the declared receiving section's clock",
        });
    }
    drop(word);
    let first = phases.first_epoch();
    let reads = anchors
        .iter()
        .take(section.length)
        .enumerate()
        .map(|(station, anchor)| {
            Ok(StationRead {
                station,
                crossing: first + station,
                tick: opened_at + first + station,
                read: phases.read(field, material, current, anchor)?,
            })
        })
        .collect::<Result<Vec<_>, HnnError>>()?;
    let admitted = domain_classes(section);
    let cells = placed
        .iter()
        .enumerate()
        .map(|(t, cell)| match cell {
            Some(class) => Ok(RepairedCell::Intact(*class)),
            None => decide_station(
                t,
                &admitted,
                if t < reads.len() {
                    Unresolved::UncertifiedDomain
                } else {
                    Unresolved::Unread
                },
            ),
        })
        .collect::<Result<Vec<_>, HnnError>>()?;
    Ok(PhysicalRepair {
        cells,
        reads,
        opening: opening_receipt,
        balances,
        word: balance,
        carry,
    })
}

/// [definition; agent-inferred, October 5] **The classes an erased station's domain projects
/// to**: a release needs the domain of the word's coupled drive, certified, projected through the
/// executed anchor map and the decoder. No owner certifies that domain: a component domain under a
/// frozen drive (`holon::parametron::DomainProposal`) is not the word's state-dependent drive, a
/// local tangent rank is not a domain, and a point reading is one state. Uncertified, the domain is
/// the whole state space, whose projection lies within every class of the encoding, so the fibre is
/// the encoding's classes. (`PeriodicLock::phase_class` is a pump phase index, not a class.)
fn domain_classes(section: &DamagedSection) -> Vec<usize> {
    (0..section.classes).collect()
}

/// **The one decision on an erased station**: its class reading over the domain has width zero
/// exactly when the domain projects to one class, decided by `receiver::release` at tolerance
/// zero: released, or held with the projected classes as its fibre.
fn decide_station(
    station: usize,
    admitted: &[usize],
    unresolved: Unresolved,
) -> Result<RepairedCell, HnnError> {
    let rule = DecisionRule::new(
        "the physical repair's commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let (diameter, attaining, read) = if admitted.len() == 1 {
        (Rat::zero(), WidthWitness::Point, 1)
    } else {
        (
            Rat::one(),
            WidthWitness::Pair { left: 0, right: 1 },
            admitted.len().max(2),
        )
    };
    let width = ReceiverWidth::declared(
        format!("the physically repaired station {station}"),
        "the station's class over the projection of its word's domain through the decoder",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        read,
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, true)?;
    Ok(match release(&rule, &options)? {
        ReleaseReturn::Released { .. } => RepairedCell::Released(admitted[0]),
        _ => RepairedCell::Held {
            fibre: admitted.to_vec(),
            unresolved,
        },
    })
}
